// ── RIO DE JANEIRO — Sugarloaf, Christ the Redeemer, Copacabana ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — all provided by the runtime

// Sky gradient override
svg += `<defs><linearGradient id="lg-rio" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${isN ? '#0B1E3D' : sc.sky1}"/><stop offset="100%" stop-color="${isN ? '#091428' : sc.sky2}"/></linearGradient></defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-rio)"/>`;

// Ocean
const oceanY = h * 0.65;
svg += `<rect x="0" y="${oceanY}" width="${w}" height="${h - oceanY}" fill="${isN ? '#0A2540' : '#1CA3EC'}"/>`;

// Animated ocean waves
for (let i = 0; i < 6; i++) {
  const wyv = oceanY + i * 6 + Math.sin(mt * 2 + i) * 3;
  svg += `<path d="M0 ${wyv} Q ${w * 0.25} ${wyv + 5 * w1} ${w * 0.5} ${wyv} T ${w} ${wyv}" fill="none" stroke="${isN ? '#4FC3F7' : '#ffffff'}" stroke-opacity="0.4" stroke-width="2"/>`;
}

// Beach (Copacabana)
svg += `<rect x="0" y="${oceanY - 20}" width="${w}" height="20" fill="${sc.ground}"/>`;
// Wave mosaic (Copacabana pattern)
for (let i = 0; i < 18; i++) {
  const px2 = i * (w / 18);
  const poff = Math.sin(i * 0.8 + mt) * 2;
  svg += `<path d="M${px2} ${oceanY - 10 + poff} q10 -5 20 0" stroke="#5A4A3A" stroke-width="1" fill="none" opacity="0.35"/>`;
}

// Sugarloaf Mountain
const sugarX = w * 0.75;
const sugarH = 120 + w2 * 20;
svg += `<path d="M ${sugarX - 80} ${bY} Q ${sugarX} ${bY - sugarH} ${sugarX + 60} ${bY} Z" fill="#4B5D67" stroke="#2C3E50" stroke-width="${ol}"/>`;
// Sugarloaf highlight
svg += `<path d="M ${sugarX - 20} ${bY - sugarH * 0.9} Q ${sugarX} ${bY - sugarH} ${sugarX + 20} ${bY - sugarH * 0.85}" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="2"/>`;

// Cable car wire + animated gondola
const cableT = w1;
const carX = sugarX - 120 + cableT * 140;
const carY = bY - sugarH * 0.7 + Math.sin(mt * 2) * 5;
svg += `<line x1="${sugarX - 120}" y1="${bY - sugarH * 0.6}" x2="${sugarX + 10}" y2="${bY - sugarH * 0.9}" stroke="#222" stroke-width="1.5"/>`;
svg += `<rect x="${carX - 6}" y="${carY - 5}" width="12" height="10" fill="${sc.acc}" rx="2" stroke="#2C3E50" stroke-width="${ol * 0.4}"/>`;

// Christ the Redeemer
const christX = w * 0.3;
const christY = bY - 145;
svg += `<rect x="${christX - 5}" y="${christY}" width="10" height="32" fill="#DDD" stroke="#AAA" stroke-width="${ol * 0.5}"/>`;
svg += `<rect x="${christX - 26}" y="${christY + 10}" width="52" height="8" fill="#DDD" stroke="#AAA" stroke-width="${ol * 0.5}"/>`;
if (isN) {
  svg += `<circle cx="${christX}" cy="${christY}" r="${12 + w3 * 4}" fill="none" stroke="rgba(255,255,255,0.45)" stroke-width="2"/>`;
  svg += `<ellipse cx="${christX}" cy="${christY + 16}" rx="${30 + w2 * 5}" ry="10" fill="rgba(255,255,220,0.06)"/>`;
}

// City skyline
for (let i = 0; i < 13; i++) {
  const sx = i * (w / 13);
  const shgt = 30 + Math.sin(i * 0.9) * 10 + w2 * 15;
  svg += `<rect x="${sx}" y="${bY - shgt}" width="${w / 15}" height="${shgt}" fill="${sc.bld}"/>`;
  if (isN) {
    for (let j = 0; j < 3; j++) {
      const lp = Math.sin(mt * 2.1 + i * 0.7 + j * 1.1) * 0.5 + 0.5;
      svg += `<rect x="${sx + 3}" y="${bY - shgt + 5 + j * 10}" width="3" height="3" fill="#FFD54F" opacity="${0.4 + lp * 0.6}"/>`;
    }
  }
}

// Palm trees (3 on the beach)
for (let i = 0; i < 3; i++) {
  const ptx = w * 0.08 + i * 65;
  svg += `<rect x="${ptx}" y="${bY - 42}" width="6" height="42" fill="#6B4F2A"/>`;
  for (let k = 0; k < 5; k++) {
    const ang = k * 0.65 - 1.3 + Math.sin(mt * 0.9 + i) * 0.2;
    const lx2 = ptx + 3 + Math.cos(ang) * 22;
    const ly2 = (bY - 42) + Math.sin(ang) * 22;
    svg += `<line x1="${ptx + 3}" y1="${bY - 42}" x2="${lx2}" y2="${ly2}" stroke="#2E7D32" stroke-width="3" stroke-linecap="round"/>`;
  }
}

// Atmospheric sun glow (day) / moon (night)
if (!isN) {
  svg += `<circle cx="${w * 0.82}" cy="${h * 0.18}" r="${55 + w1 * 15}" fill="#FFD180" opacity="0.18"/>`;
  svg += `<circle cx="${w * 0.82}" cy="${h * 0.18}" r="28" fill="#FFE082" opacity="0.55"/>`;
} else {
  svg += `<circle cx="${w * 0.82}" cy="${h * 0.18}" r="22" fill="#EDE8DF" opacity="0.85"/>`;
  svg += `<circle cx="${w * 0.82 + 6}" cy="${h * 0.18 - 6}" r="18" fill="${isN ? '#0B1E3D' : sc.sky2}" opacity="0.9"/>`;
}
